with base as (select id, dept_id, hire_date, is_remote, level, initcap(trim(job_title)) job_title_title from employees where job_title is not null and hire_date > to_date('2023-05-07')) select date_trunc('month', hire_date) as activity_month, dept_id, count(*) filter (where level = 'L4') as l4_rows, size(collect_set(level)) as num_levels, count(case when level = 'L2' then 1 end) as l2_count, count(case when level = 'L1' then 1 end) as l1_count from base group by date_trunc('month', hire_date), dept_id having l2_count >= 1 order by dept_id desc nulls first;
